import{_ as a,o as n,c as i,am as t}from"./chunks/framework.CiF4W93w.js";const c=JSON.parse('{"title":"OAuth 方式进行授权 - 概念理解","description":"","frontmatter":{"title":"OAuth 方式进行授权 - 概念理解","excerpt":"摘要","date":"2025-11-23 10:29:24","updated":"2025-11-23 10:29:24"},"headers":[],"relativePath":"架构篇/分布式系统/分布式授权访问/OAuth 方式进行授权 - 概念理解.md","filePath":"架构篇/分布式系统/分布式授权访问/OAuth 方式进行授权 - 概念理解.md","lastUpdated":null}'),e={name:"架构篇/分布式系统/分布式授权访问/OAuth 方式进行授权 - 概念理解.md"};function l(r,s,p,h,o,E){return n(),i("div",null,[...s[0]||(s[0]=[t(`<h3 id="一个生动的比喻-酒店门卡" tabindex="-1">一个生动的比喻：酒店门卡 <a class="header-anchor" href="#一个生动的比喻-酒店门卡" aria-label="Permalink to &quot;一个生动的比喻：酒店门卡&quot;">​</a></h3><p>假设你去一个酒店入住，你想让朋友帮你去房间拿个东西，但你不想给他你的房间钥匙（主密码），也不想他每次来都找你开门。</p><ol><li><strong>你（资源所有者）</strong> 去<strong>前台（授权服务器）</strong>。</li><li>你告诉前台：“我想给<strong>我的朋友（第三方应用）</strong> 开一张能进入<strong>我房间（受保护资源）</strong> 的门卡，但只能进出一次，并且只能开房门，不能开迷你吧。”</li><li>前台说：“可以，请让你的朋友先来我这里登记一下。”</li><li>你的朋友来到前台，前台<strong>向你确认（征得用户同意）</strong>：“您是否授权这位朋友获得一张限时门卡？” 你确认“是”。</li><li>前台核实了朋友的身份后，并没有直接给他门卡，而是给了他一个<strong>凭证单（授权码 Authorization Code）</strong>。</li><li>你的朋友拿着这个凭证单，再次回到前台。</li><li>前台确认凭证单有效后，才<strong>发放了一张限时、限功能的门卡（访问令牌 Access Token）</strong> 给他。</li><li>你的朋友拿着这张门卡，就可以直接去<strong>房间门口（资源服务器）</strong> 刷卡进门了，无需再经过你的同意。</li></ol><p>这个“凭证单”就是 OAuth 流程安全的关键。</p><hr><h3 id="oauth-2-0-的核心角色" tabindex="-1">OAuth 2.0 的核心角色 <a class="header-anchor" href="#oauth-2-0-的核心角色" aria-label="Permalink to &quot;OAuth 2.0 的核心角色&quot;">​</a></h3><p>在正式讲流程前，先明确四个核心角色：</p><ol><li><strong>资源所有者 (Resource Owner)</strong>： 拥有受保护数据的人，即<strong>用户</strong>。在比喻中就是“你”。</li><li><strong>客户端 (Client)</strong>： 想要访问用户数据的第三方应用。在比喻中就是“你的朋友”。</li><li><strong>授权服务器 (Authorization Server)</strong>： 专门负责处理授权、验证用户身份、并颁发令牌的服务器。这是 OAuth 流程的核心。在比喻中就是“酒店前台”。</li><li><strong>资源服务器 (Resource Server)</strong>： 存放用户受保护数据的 API 服务器。客户端最终拿着令牌来这里取数据。在比喻中就是“房间门”以及门背后的房间。通常授权服务器和资源服务器属于同一个服务商（例如 Google），但在逻辑上是分开的。</li></ol><h3 id="最常用的流程-授权码模式" tabindex="-1">最常用的流程：授权码模式 <a class="header-anchor" href="#最常用的流程-授权码模式" aria-label="Permalink to &quot;最常用的流程：授权码模式&quot;">​</a></h3><p>这是最安全、最完整的流程，用于有后端的 Web 应用。其流程图如下：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant User as 用户 (资源所有者)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Client as 第三方应用 (客户端)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant AuthServer as 授权服务器</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant ResourceServer as 资源服务器</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over User, Client: 1. 初始化授权请求</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Client-&gt;&gt;User: 点击“通过Google登录”</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over User, AuthServer: 2. 用户认证与授权</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    User-&gt;&gt;AuthServer: 被重定向到授权服务器</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AuthServer-&gt;&gt;User: 要求登录并询问是否授权</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    User-&gt;&gt;AuthServer: 登录并同意授权</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over AuthServer, Client: 3. 颁发授权码</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AuthServer-&gt;&gt;Client: 通过重定向返回授权码</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over Client, AuthServer: 4. 用授权码换取访问令牌</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Client-&gt;&gt;AuthServer: 发送授权码和客户端密钥&lt;br&gt;请求访问令牌</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AuthServer-&gt;&gt;Client: 返回访问令牌 (和刷新令牌)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over Client, ResourceServer: 5. 使用访问令牌调用API</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Client-&gt;&gt;ResourceServer: 在请求头中携带访问令牌</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ResourceServer-&gt;&gt;Client: 返回受保护的资源数据</span></span></code></pre></div><p>参考链接</p><ul><li><a href="https://www.justauth.cn/guide/quickstart/oauth/" target="_blank" rel="noreferrer">https://www.justauth.cn/guide/quickstart/oauth/</a></li></ul>`,13)])])}const k=a(e,[["render",l]]);export{c as __pageData,k as default};
